package org.systemmaster.core;
import java.time.Instant; import java.util.*;
public record CapabilityDescriptor(String capabilityId,String version,String owner,String purpose,Set<String> semanticTags,String inputSchemaRef,String outputSchemaRef,String qualificationState,List<String> qualificationEvidenceRefs,Set<EffectClass> effectClasses,List<String> authorityRequirements,String determinismClass,String idempotencyClass,String retryPolicyRef,String reconciliationPolicyRef,String compensationPolicyRef,List<String> preconditionContractRefs,List<String> postconditionContractRefs,List<String> concurrencyDomains,boolean offlineCapable,boolean networkRequired,List<String> egressRequirements,List<String> dataZoneRequirements,String sandboxProfile,String resourceProfileRef,String latencyProfile,List<String> modelRequirements,List<String> hardwareRequirements,String health,Instant healthObservedAt,Integer healthTtlSeconds,String implementationDigest,String compatibilityRange,List<String> supersedes,Map<String,String> protocolBindings,List<String> allowedCallers,String provenanceRef){
 public CapabilityDescriptor { if(capabilityId==null||capabilityId.isBlank()||capabilityId.length()>256)throw new IllegalArgumentException("invalid capabilityId");if(version==null||version.isBlank()||version.length()>128)throw new IllegalArgumentException("invalid version");if(owner==null||owner.isBlank()||owner.length()>256)throw new IllegalArgumentException("invalid owner");if(purpose==null||purpose.isBlank()||purpose.length()>2048)throw new IllegalArgumentException("invalid purpose"); semanticTags=semanticTags==null?Set.of():Set.copyOf(semanticTags);qualificationEvidenceRefs=qualificationEvidenceRefs==null?List.of():List.copyOf(qualificationEvidenceRefs);effectClasses=effectClasses==null?Set.of():Set.copyOf(effectClasses);authorityRequirements=authorityRequirements==null?List.of():List.copyOf(authorityRequirements);preconditionContractRefs=preconditionContractRefs==null?List.of():List.copyOf(preconditionContractRefs);postconditionContractRefs=postconditionContractRefs==null?List.of():List.copyOf(postconditionContractRefs);concurrencyDomains=concurrencyDomains==null?List.of():List.copyOf(concurrencyDomains);egressRequirements=egressRequirements==null?List.of():List.copyOf(egressRequirements);dataZoneRequirements=dataZoneRequirements==null?List.of():List.copyOf(dataZoneRequirements);modelRequirements=modelRequirements==null?List.of():List.copyOf(modelRequirements);hardwareRequirements=hardwareRequirements==null?List.of():List.copyOf(hardwareRequirements);supersedes=supersedes==null?List.of():List.copyOf(supersedes);protocolBindings=protocolBindings==null?Map.of():Map.copyOf(protocolBindings);allowedCallers=allowedCallers==null?List.of():List.copyOf(allowedCallers); if(semanticTags.size()>64||allowedCallers.size()>128||authorityRequirements.size()>128)throw new IllegalArgumentException("capability descriptor cardinality exceeded");if(healthTtlSeconds!=null&&(healthTtlSeconds<1||healthTtlSeconds>86400))throw new IllegalArgumentException("health TTL out of range");if("HEALTHY".equals(health)&&(healthObservedAt==null||healthTtlSeconds==null))throw new IllegalArgumentException("HEALTHY requires observation and TTL");for(String a:allowedCallers){if(a==null||a.isBlank()||a.length()>256)throw new IllegalArgumentException("invalid allowed caller");if(a.contains("*")&&!a.endsWith("/*"))throw new IllegalArgumentException("wildcard only allowed as namespace suffix /*");} }
 public boolean currentlyHealthy(Instant now){Objects.requireNonNull(now,"now");if(!"HEALTHY".equals(health)||healthObservedAt==null||healthTtlSeconds==null)return false;return now.isBefore(healthObservedAt.plusSeconds(healthTtlSeconds));}
}
